optimization-trial.patch:
diff --git a/tools/bot-evaluation/src/xml.rs b/tools/bot-evaluation/src/xml.rs
index 3accb4ad..b97531bc 100644
--- a/tools/bot-evaluation/src/xml.rs
+++ b/tools/bot-evaluation/src/xml.rs
@@ -139,8 +139,8 @@ pub fn parse(source: &str, root: &str) -> Result<Value> {
 }
 fn emit(writer: &mut Writer<Vec<u8>>, name: &str, value: &Value) -> Result<()> {
     if !name
-        .chars()
-        .all(|c| c.is_ascii_alphanumeric() || "_-".contains(c))
+        .bytes()
+        .all(|c| c.is_ascii_alphanumeric() || b"_-".contains(&c))
     {
         return Err("Invalid XML field".into());
     }
@@ -194,12 +194,12 @@ fn emit(writer: &mut Writer<Vec<u8>>, name: &str, value: &Value) -> Result<()> {
     Ok(())
 }
 pub fn fragment(name: &str, value: &Value) -> Result<Vec<u8>> {
-    let mut writer = Writer::new(Vec::new());
+    let mut writer = Writer::new(Vec::with_capacity(16 * 1024));
     emit(&mut writer, name, value)?;
     Ok(writer.into_inner())
 }
 pub fn encode(root: &str, value: &Value) -> Result<Vec<u8>> {
-    let mut w = Writer::new(Vec::new());
+    let mut w = Writer::new(Vec::with_capacity(16 * 1024));
     w.write_event(Event::Decl(BytesDecl::new("1.0", Some("UTF-8"), None)))?;
     let mut start = BytesStart::new(root);
     start.push_attribute(("schema_version", "1"));
